#!/usr/bin/env tsx

import fs from 'node:fs/promises';
import path from 'node:path';

import { buildGeneratedKoreanBroadAmbiguitySurfaces } from './lib/build-korean-broad-ambiguity-surfaces.js';

const OUTPUT_PATH = path.resolve(
  process.cwd(),
  'src/domain/query/service/generated/korean-broad-ambiguity-surfaces.ts',
);

const GENERATED_HEADER = `/**
 * Generated by scripts/generate-korean-broad-ambiguity-surfaces.ts.
 *
 * Source graph:
 * - data/gold-wine-catalog.jsonl
 * - scripts/seed-wines-real.ts
 * - generated exact alias catalogs
 *
 * Contract:
 * - only auto-promoted gold/seed Korean exact aliases are eligible
 * - broadness is admitted only when proven by source-graph structure:
 *   producer family cardinality and/or multi-entity proper-superphrase support
 * - curated exact aliases remain outside this automatic ambiguity lane
 */

export type GeneratedBroadAmbiguityClassifier =
  | 'producer_family'
  | 'cross_producer_shared_surface'
  | 'multi_entity_generic_surface';

export interface GeneratedKoreanBroadAmbiguitySurfaceEntry {
  readonly term: string;
  readonly types: readonly string[];
  readonly severity: 'high';
  readonly classifiers: readonly GeneratedBroadAmbiguityClassifier[];
  readonly sources: readonly ('gold_catalog' | 'seed_catalog')[];
  readonly supportingCanonicalValues: readonly string[];
}

export const GENERATED_KOREAN_BROAD_AMBIGUITY_SURFACES:
readonly GeneratedKoreanBroadAmbiguitySurfaceEntry[] = [
`;

const GENERATED_FOOTER = `] as const;
`;

async function run(): Promise<void> {
  const entries = await buildGeneratedKoreanBroadAmbiguitySurfaces();
  const lines = entries.map((entry) =>
    `  { term: ${JSON.stringify(entry.term)}, types: ${JSON.stringify(entry.types)}, severity: 'high', classifiers: ${JSON.stringify(entry.classifiers)}, sources: ${JSON.stringify(entry.sources)}, supportingCanonicalValues: ${JSON.stringify(entry.supportingCanonicalValues)} },`,
  );

  const content = `${GENERATED_HEADER}${lines.join('\n')}\n${GENERATED_FOOTER}`;
  await fs.mkdir(path.dirname(OUTPUT_PATH), { recursive: true });
  await fs.writeFile(OUTPUT_PATH, content, 'utf8');
  console.log(`Wrote ${entries.length} generated Korean broad ambiguity surfaces to ${OUTPUT_PATH}`);
}

void run().catch((error: unknown) => {
  const message = error instanceof Error ? error.stack ?? error.message : String(error);
  console.error(message);
  process.exit(1);
});
